"use client";

/**
 * Toggle and ToggleGroup. The quiet key of a toolbar: bold, italic, grid or
 * list, a filter. Where LedKey announces a state with a light, a Toggle says
 * "on" the way a latching key does: the cap stays down in its well. Pressed
 * on, it travels down and holds there; pressed off, it springs back up.
 *
 * A ToggleGroup puts its Toggles in one long well, like keys on one bar,
 * with arrow-key focus between them. `multiple` lets any number be on (bold
 * and italic); without it, at most one (align left, centre, right). For
 * "exactly one of a few, always one", use Segmented.
 *
 * Base UI Toggle and ToggleGroup own `aria-pressed`, the roving focus and
 * the group's value; Echo owns the cap and its travel. Sizes are the control
 * scale, and read a SizeProvider. Inside a Toolbar they render through its
 * parts, so they join its one tab stop and arrow-key order.
 */
import { forwardRef, useCallback, type MutableRefObject, type ReactNode } from "react";
import { Toggle as BaseToggle } from "@base-ui/react/toggle";
import { ToggleGroup as BaseToggleGroup } from "@base-ui/react/toggle-group";
import { Toolbar as BaseToolbar } from "@base-ui/react/toolbar";
import { useInToolbar } from "../toolbar/toolbar-context";
import { useCapPhysics } from "echo-ui-core/tactile";
import type { EchoInterop } from "echo-ui-core/types";
import { useSoundOptional } from "echo-ui-core/sound";
import { SizeProvider, useControlSize, type ControlSize } from "../size";
import "./toggle.css";

interface ToggleOwnProps extends EchoInterop {
  /** The legend, when it has words. */
  children?: ReactNode;
  /** An icon; icon-only toggles need `aria-label`. */
  icon?: ReactNode;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
  /** Its value inside a ToggleGroup. */
  value?: string;
  /** Height on the control scale. Defaults to the group's or SizeProvider's size. */
  size?: ControlSize;
}

type ToggleName =
  | { children: ReactNode; "aria-label"?: string }
  | { children?: undefined; "aria-label": string };

export type ToggleProps = ToggleOwnProps & ToggleName;

export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(function Toggle(
  { children, icon, pressed, defaultPressed, onPressedChange, value, disabled, size: ownSize, ...interop },
  ref,
) {
  const size = useControlSize(ownSize);
  const sound = useSoundOptional();
  const inToolbar = useInToolbar();
  const cap = useCapPhysics<HTMLButtonElement>({ travel: 1, tilt: 3 });
  const setRef = useCallback(
    (node: HTMLButtonElement | null) => {
      cap.ref(node);
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<HTMLButtonElement | null>).current = node;
    },
    [ref, cap],
  );
  const cap_ = (
    <BaseToggle
      ref={setRef}
      className="echo-toggle__cap"
      {...(pressed !== undefined ? { pressed } : {})}
      {...(defaultPressed !== undefined ? { defaultPressed } : {})}
      {...(value !== undefined ? { value } : {})}
      {...(disabled !== undefined ? { disabled } : {})}
      onPressedChange={(next) => {
        sound?.play("tap");
        onPressedChange?.(next);
      }}
      {...interop}
      {...cap.handlers}
    >
      {icon ? (
        <span className="echo-toggle__icon" aria-hidden="true">
          {icon}
        </span>
      ) : null}
      {children != null ? <span className="echo-toggle__label">{children}</span> : null}
    </BaseToggle>
  );

  return (
    <span className="echo-toggle" data-size={size} data-icon-only={children == null ? "" : undefined}>
      {inToolbar ? <BaseToolbar.Button render={cap_} /> : cap_}
    </span>
  );
});

type GroupName = { "aria-label": string; "aria-labelledby"?: string } | { "aria-labelledby": string; "aria-label"?: string };

interface ToggleGroupOwnProps {
  /** Toggles, each with a `value`. */
  children: ReactNode;
  /** The values that are on (controlled). */
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
  /** Any number can be on. Without it, at most one. Default false. */
  multiple?: boolean;
  orientation?: "horizontal" | "vertical";
  disabled?: boolean;
  /** Height on the control scale for every Toggle inside. */
  size?: ControlSize;
}

export type ToggleGroupProps = ToggleGroupOwnProps & GroupName;

export function ToggleGroup({
  children,
  value,
  defaultValue,
  onValueChange,
  multiple = false,
  orientation = "horizontal",
  disabled,
  size: ownSize,
  ...name
}: ToggleGroupProps) {
  const size = useControlSize(ownSize);
  const inToolbar = useInToolbar();
  const group = (
    <BaseToggleGroup
      className="echo-toggle-group"
      data-size={size}
      multiple={multiple}
      orientation={orientation}
      {...(value !== undefined ? { value } : {})}
      {...(defaultValue !== undefined ? { defaultValue } : {})}
      {...(disabled !== undefined ? { disabled } : {})}
      onValueChange={(next) => onValueChange?.(next as string[])}
      {...name}
    >
      {/* Every Toggle inside takes the group's size. */}
      <SizeProvider size={size}>{children}</SizeProvider>
    </BaseToggleGroup>
  );
  return inToolbar ? <BaseToolbar.Group render={group} /> : group;
}

/**
 * Toggle. A small neutral cap in its own well; "on" is the cap held down,
 * a little darker and closer to the floor, with no light. A ToggleGroup is
 * one long well holding several caps. On the control scale: the outer height
 * (well included) is sm 32, md 44, lg 60px.
 */
.echo-toggle,
.echo-toggle-group {
  --tg-well: var(--echo-space-2, 4px);
  --ctl-h: var(--echo-control-default);
  --tg-px: var(--echo-space-7);
  --tg-font: var(--echo-text-xs);
  --tg-icon: var(--echo-icon-md, 16px);
}
.echo-toggle[data-size="sm"],
.echo-toggle-group[data-size="sm"] {
  --tg-well: var(--echo-space-1, 2px);
  --ctl-h: var(--echo-control-compact);
  --tg-px: var(--echo-space-5);
  --tg-font: var(--echo-text-2xs);
  --tg-icon: var(--echo-icon-sm, 14px);
}
.echo-toggle[data-size="lg"],
.echo-toggle-group[data-size="lg"] {
  --ctl-h: var(--echo-control-large);
  --tg-px: var(--echo-space-9);
  --tg-font: var(--echo-text-sm);
}

/* The well: one per Toggle, or one for the whole group. */
.echo-toggle,
.echo-toggle-group {
  display: inline-flex;
  box-sizing: border-box;
  height: var(--ctl-h);
  padding: var(--tg-well);
  gap: var(--tg-well);
  border-radius: var(--echo-radius-lg);
  box-shadow: var(
    --echo-shadow-well,
    inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
}
.echo-toggle-group[data-orientation="vertical"] {
  flex-direction: column;
  height: auto;
}
/* Inside a group the group is the well; each Toggle is just its cap. */
.echo-toggle-group .echo-toggle {
  height: 100%;
  padding: 0;
  box-shadow: none;
}
.echo-toggle-group[data-orientation="vertical"] .echo-toggle {
  height: calc(var(--ctl-h) - 2 * var(--tg-well));
}

.echo-toggle__cap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--echo-space-3);
  box-sizing: border-box;
  height: 100%;
  min-width: calc(var(--ctl-h) - 2 * var(--tg-well));
  padding: 0 var(--tg-px);
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  color: var(--echo-text-dim);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--tg-font);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 45%, var(--echo-cap-shadow) 100%);
  box-shadow:
    inset 0 1px 0 rgb(255 255 255 / calc(0.32 * var(--echo-gloss, 1))),
    0 calc(2px - 1px * var(--press, 0)) 0 var(--echo-seam),
    0 calc(4px + 2px * var(--lift, 0)) calc(6px + 4px * var(--lift, 0)) color-mix(in oklab, var(--echo-cast-ink, black) calc(0.45 * var(--echo-shade, 1) * 100%), transparent);
  /* Held down: the latch keeps it on its seam. By `top`: useCapPhysics owns
     transform, and GSAP writes translate inline as it presses. */
  top: 0;
  transition:
    top var(--echo-duration-pop) var(--echo-ease-pop),
    box-shadow var(--echo-duration-swap) ease,
    color var(--echo-duration-swap) ease;
  will-change: transform;
}
.echo-toggle[data-icon-only] .echo-toggle__cap {
  padding: 0;
  width: calc(var(--ctl-h) - 2 * var(--tg-well));
}
.echo-toggle__cap[data-pressed] {
  top: 1.5px;
  color: var(--echo-text);
  background: linear-gradient(180deg, var(--echo-cap) 0%, var(--echo-cap-shadow) 100%);
  box-shadow:
    inset 0 1px 2px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.45 * var(--echo-shade, 1) * 100%), transparent),
    0 0.5px 0 var(--echo-seam);
}
/* The hit area is the full height, well included. */
.echo-toggle__cap::after {
  content: "";
  position: absolute;
  inset-block: calc(-1 * var(--tg-well));
  inset-inline: 0;
}
.echo-toggle__cap:focus-visible {
  outline: 2px solid transparent;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}
.echo-toggle__cap[data-disabled] {
  cursor: default;
  opacity: 0.45;
}
.echo-toggle__icon {
  display: inline-flex;
  width: var(--tg-icon);
  height: var(--tg-icon);
}
.echo-toggle__icon > svg {
  width: 100%;
  height: 100%;
}
@media (pointer: coarse) {
  .echo-toggle[data-size="sm"],
  .echo-toggle-group[data-size="sm"] {
    --ctl-h: 44px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .echo-toggle__cap {
    transition: none;
  }
}
/* Forced colors draws "on" as a system highlight: state can't live in a shade. */
@media (forced-colors: active) {
  .echo-toggle__cap {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-toggle__cap[data-pressed] {
    background: Highlight;
    color: HighlightText;
    border-color: Highlight;
  }
  .echo-toggle__cap:focus-visible {
    outline-color: Highlight;
  }
}
